<template><div class="page-shell"><header class="page-header"><div><h2>课程管理</h2><p>维护课程基础信息、授课教师与开课状态</p></div><button class="primary-btn" @click="openCreate">新增课程</button></header><section class="stats"><div><span>课程总数</span><strong>{{ total }}</strong></div><div><span>本页进行中</span><strong>{{ courses.filter(c=>c.courseStatus===1).length }}</strong></div><div><span>本页选课人数</span><strong>{{ courses.reduce((n,c)=>n+c.studentCount,0) }}</strong></div></section><section class="filters"><label><span>关键字</span><input v-model.trim="filter.keyword" @keyup.enter="search" placeholder="课程名称或编码" /></label><label><span>学期</span><input v-model.trim="filter.semester" @keyup.enter="search" placeholder="如 2026-2027-1" /></label><label><span>状态</span><select v-model="filter.status"><option value="">全部</option><option :value="1">进行中</option><option :value="2">已结课</option><option :value="3">已归档</option></select></label><button class="ghost-btn" @click="reset">重置</button><button class="dark-btn" @click="search">查询</button></section><p v-if="message" class="message">{{ message }}</p><section class="table-card"><div v-if="loading" class="state">正在加载…</div><div v-else-if="courses.length===0" class="state">暂无课程</div><div v-else class="scroll"><table><thead><tr><th>课程</th><th>学期</th><th>授课教师</th><th>所属部门</th><th>选课人数</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="c in courses" :key="c.courseId"><td><button class="link" @click="view(c.courseId)">{{ c.courseName }}</button><small>{{ c.courseCode }}</small></td><td>{{ c.semester }}</td><td>{{ c.teacherName }}</td><td>{{ c.departmentName || '未设置' }}</td><td>{{ c.studentCount }}</td><td><span class="status"><i :class="c.courseStatus===1?'on':'off'"></i>{{ courseStatusLabel(c.courseStatus) }}</span></td><td><div class="actions"><button @click="view(c.courseId)">查看</button><button @click="edit(c.courseId)">编辑</button><button v-if="c.courseStatus!==3" @click="archive(c)">归档</button></div></td></tr></tbody></table></div><footer><span>共 {{ total }} 条，第 {{ pageNum }} / {{ pages }} 页</span><div><button :disabled="pageNum<=1" @click="go(pageNum-1)">上一页</button><button :disabled="pageNum>=pages" @click="go(pageNum+1)">下一页</button></div></footer></section>
<teleport to="body"><div v-if="dialog" class="overlay" @click.self="dialog=false"><section class="modal"><header><div><h3>{{ mode==='create'?'新增课程':mode==='edit'?'编辑课程':'课程详情' }}</h3><p>课程编码创建后不可修改</p></div><button class="close" @click="dialog=false">×</button></header><div class="body"><div class="grid"><label><span>课程编码 *</span><input v-model.trim="form.courseCode" :disabled="mode!=='create'" /></label><label><span>课程名称 *</span><input v-model.trim="form.courseName" :disabled="mode==='view'" /></label><label><span>学期 *</span><input v-model.trim="form.semester" :disabled="mode==='view'" /></label><label><span>学分 *</span><input v-model.number="form.credit" type="number" min="1" :disabled="mode==='view'" /></label><label><span>总学时 *</span><input v-model.number="form.totalHours" type="number" min="1" :disabled="mode==='view'" /></label><label><span>授课教师 *</span><select v-model="form.teacherId" :disabled="mode==='view'"><option :value="0" disabled>请选择</option><option v-for="t in teachers" :key="t.id" :value="t.id">{{ t.personName }}</option></select></label><label><span>所属部门</span><select v-model="form.departmentId" :disabled="mode==='view'"><option value="">暂不设置</option><option v-for="d in departments" :key="d.id" :value="d.id">{{ d.departmentName }}</option></select></label><label v-if="mode!=='create'"><span>课程状态</span><select v-model="form.courseStatus" :disabled="mode==='view'"><option :value="1">进行中</option><option :value="2">已结课</option><option :value="3">已归档</option></select></label><label class="full"><span>课程描述</span><textarea v-model.trim="form.description" rows="3" :disabled="mode==='view'"></textarea></label><label class="full"><span>教学大纲</span><textarea v-model.trim="form.syllabus" rows="4" :disabled="mode==='view'"></textarea></label></div><div v-if="mode==='view'" class="students"><strong>选课学生（{{ studentList.length }}）</strong><span v-if="studentList.length===0">暂无学生</span><span v-for="s in studentList" :key="s.personId">{{ s.personName }} · {{ s.studentNo || '无学号' }} · {{ s.className || '未填写班级' }}</span></div><p v-if="formError" class="error">{{ formError }}</p></div><footer class="modal-footer"><button class="ghost-btn" @click="dialog=false">关闭</button><button v-if="mode!=='view'" class="primary-btn" :disabled="saving" @click="save">保存</button></footer></section></div></teleport></div></template>
<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { archiveCourse,courseStatusLabel,createCourse,getCourseDetail,getCoursePage,getCourseStudents,updateCourse,type CourseListItem,type CourseStatus,type CourseStudent } from '../../utils/teachingApi'
import { getDepartmentTree,getPersonPage,type DepartmentItem,type PersonDetail } from '../../utils/personnelApi'
const courses=ref<CourseListItem[]>([]),teachers=ref<PersonDetail[]>([]),departments=ref<DepartmentItem[]>([]),studentList=ref<CourseStudent[]>([]);const total=ref(0),pageNum=ref(1),loading=ref(false),saving=ref(false),dialog=ref(false),editingId=ref(0),message=ref(''),formError=ref('');const pageSize=10;const mode=ref<'create'|'edit'|'view'>('create');const filter=reactive<{keyword:string;semester:string;status:CourseStatus|''}>({keyword:'',semester:'',status:''});const form=reactive({courseCode:'',courseName:'',semester:'',credit:1,totalHours:16,teacherId:0,departmentId:'' as number|'',courseStatus:1 as CourseStatus,description:'',syllabus:''});const pages=computed(()=>Math.max(1,Math.ceil(total.value/pageSize)));const flat=(x:DepartmentItem[]):DepartmentItem[]=>x.flatMap(i=>[i,...flat(i.children||[])]);const err=(e:unknown)=>e instanceof Error?e.message:'操作失败';async function load(){loading.value=true;try{const p=await getCoursePage({pageNum:pageNum.value,pageSize,keyword:filter.keyword||undefined,semester:filter.semester||undefined,courseStatus:filter.status===''?undefined:filter.status});courses.value=p.records;total.value=p.total}catch(e){message.value=err(e)}finally{loading.value=false}}function search(){pageNum.value=1;void load()}function go(n:number){pageNum.value=n;void load()}function reset(){filter.keyword='';filter.semester='';filter.status='';search()}function clear(){Object.assign(form,{courseCode:'',courseName:'',semester:'',credit:1,totalHours:16,teacherId:0,departmentId:'',courseStatus:1,description:'',syllabus:''});formError.value='';studentList.value=[]}function openCreate(){clear();editingId.value=0;mode.value='create';dialog.value=true}async function fill(id:number,next:'edit'|'view'){try{const d=await getCourseDetail(id);Object.assign(form,{courseCode:d.courseCode,courseName:d.courseName,semester:d.semester,credit:d.credit,totalHours:d.totalHours,teacherId:d.teacherId,departmentId:d.departmentId||'',courseStatus:d.courseStatus,description:d.description||'',syllabus:d.syllabus||''});editingId.value=id;mode.value=next;studentList.value=next==='view'?await getCourseStudents(id):[];dialog.value=true}catch(e){message.value=err(e)}}const edit=(id:number)=>fill(id,'edit'),view=(id:number)=>fill(id,'view');async function save(){if(!form.courseCode||!form.courseName||!form.semester||!form.teacherId||form.credit<1||form.totalHours<1){formError.value='请完整填写课程必填信息';return}saving.value=true;const common={courseName:form.courseName,semester:form.semester,credit:form.credit,totalHours:form.totalHours,teacherId:form.teacherId,departmentId:form.departmentId===''?undefined:form.departmentId,description:form.description||undefined,syllabus:form.syllabus||undefined,courseStatus:form.courseStatus};try{if(mode.value==='create')await createCourse({courseCode:form.courseCode,...common});else await updateCourse(editingId.value,common);dialog.value=false;await load()}catch(e){formError.value=err(e)}finally{saving.value=false}}async function archive(c:CourseListItem){if(!confirm(`确认归档“${c.courseName}”？`))return;try{await archiveCourse(c.courseId);await load()}catch(e){message.value=err(e)}}onMounted(async()=>{try{const [tree,p]=await Promise.all([getDepartmentTree(),getPersonPage({pageNum:1,pageSize:500,personTypes:[2],personStatuses:[1]})]);departments.value=flat(tree);teachers.value=p.records}catch(e){message.value=err(e)}await load()})
</script>
<style scoped>
.page-shell{height:100%;overflow:auto;padding:24px;background:transparent;color:#172033}.page-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.page-header h2{margin:0;font-size:22px}.page-header p,.modal header p{margin:5px 0 0;color:#7b8495;font-size:13px}.primary-btn,.ghost-btn,.dark-btn{border:0;border-radius:8px;padding:9px 15px;font:inherit;font-size:13px;cursor:pointer}.primary-btn{background:#2563eb;color:#fff}.ghost-btn{background:#eef1f6}.dark-btn{background:#172033;color:#fff}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:14px}.stats>div,.filters,.table-card{background:#fff;border:1px solid #e7ebf1;border-radius:12px}.stats>div{padding:16px}.stats span{display:block;color:#7b8495;font-size:12px}.stats strong{font-size:24px}.filters{display:grid;grid-template-columns:2fr 1fr 1fr auto auto;gap:10px;align-items:end;padding:15px;margin-bottom:14px}.filters label,.grid label{display:flex;flex-direction:column;gap:6px}.filters span,.grid span{font-size:12px;color:#687386}.filters input,.filters select,.grid input,.grid select,.grid textarea{box-sizing:border-box;width:100%;border:1px solid #dfe4ec;border-radius:8px;padding:9px 10px;background:#fff;font:inherit;font-size:13px}.message,.error{color:#b42336;font-size:13px}.table-card{overflow:hidden}.scroll{overflow:auto}table{width:100%;min-width:850px;border-collapse:collapse}th,td{padding:13px 14px;border-bottom:1px solid #eef1f5;text-align:left;font-size:13px}th{background:#fafbfc;color:#687386;font-size:12px}td small{display:block;color:#9098a7;margin-top:4px}.link{border:0;background:none;padding:0;color:#1d4ed8;font:inherit;font-weight:600;cursor:pointer}.status{display:flex;align-items:center;gap:6px}.status i{width:7px;height:7px;border-radius:50%;background:#dc5b61}.status i.on{background:#22a06b}.actions{display:flex;gap:6px}.actions button,.table-card>footer button{border:1px solid #dfe4ec;background:#fff;border-radius:7px;padding:6px 9px;font-size:12px}.state{padding:56px;text-align:center;color:#8992a2}.table-card>footer{display:flex;justify-content:space-between;padding:12px 14px;color:#7b8495;font-size:12px}.overlay{position:fixed;inset:0;z-index:1200;display:flex;align-items:center;justify-content:center;padding:24px;background:#0f172a6b}.modal{width:min(760px,100%);max-height:88vh;display:flex;flex-direction:column;background:#fff;border-radius:14px}.modal>header{display:flex;justify-content:space-between;padding:20px 22px;border-bottom:1px solid #eef1f5}.modal h3{margin:0}.close{border:0;background:none;font-size:24px}.body{padding:20px 22px;overflow:auto}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.grid .full{grid-column:1/-1}.grid :disabled{background:#f5f6f8}.students{display:flex;flex-direction:column;gap:7px;margin-top:18px;padding:14px;border:1px solid #e7ebf1;border-radius:9px;font-size:13px}.modal-footer{display:flex;justify-content:flex-end;gap:8px;padding:15px 22px;border-top:1px solid #eef1f5}@media(max-width:800px){.stats,.grid{grid-template-columns:1fr}.filters{grid-template-columns:1fr 1fr}.grid .full{grid-column:auto}}
</style>
